function DesktopUpdate(){const desktopParam=new URLSearchParams(window.location.search).get("desktop")==="1";if(desktopParam)try{localStorage.setItem("balticm-desktop","1")}catch{}let savedDesktop=false;try{savedDesktop=localStorage.getItem("balticm-desktop")==="1"}catch{}const desktopMode=desktopParam||savedDesktop;const[latest,setLatest]=useState(null),[desktop,setDesktop]=useState(null),[checking,setChecking]=useState(false),[installing,setInstalling]=useState(false),[message,setMessage]=useState(""),[progress,setProgress]=useState(null);const nativeInvoke=window.__TAURI__?.core?.invoke;if(!desktopMode)return null;const loadLatest=async()=>{const r=await fetch("/api/desktop/latest",{cache:"no-store"});const x=await r.json();setLatest(x);return x};const check=async()=>{setChecking(true);setMessage("");try{if(nativeInvoke){const status=await nativeInvoke("desktop_check_update");setDesktop({isDesktop:true,currentVersion:status.currentVersion});setLatest(prev=>({...prev,available:status.available,version:status.latestVersion||status.currentVersion,notes:status.notes||prev?.notes}));setMessage(status.available?"Update available.":"You are up to date.")}else{await loadLatest()}}catch(e){setMessage("Update check failed.");console.error(e)}finally{setChecking(false)}};const install=async()=>{if(!nativeInvoke)return;setInstalling(true);setProgress({stage:"starting",percent:0});setMessage("Preparing signed update…");try{await nativeInvoke("desktop_install_update")}catch(e){const detail=typeof e==="string"?e:(e?.message||String(e));setMessage("Update installation failed: "+detail);setInstalling(false);setProgress(null);console.error(e)}};useEffect(()=>{let active=true,unlisten=null;(async()=>{try{const web=await loadLatest();if(nativeInvoke){const info=await nativeInvoke("desktop_info");if(active)setDesktop(info);if(active&&info?.currentVersion&&web?.version&&!versionGt(web.version,info.currentVersion))setLatest({...web,available:false});const listen=window.__TAURI__?.event?.listen;if(listen){unlisten=await listen("desktop-update-progress",event=>{if(!active)return;const p=event.payload||{};setProgress(p);if(p.stage==="starting")setMessage("Preparing signed update…");else if(p.stage==="downloading")setMessage("Downloading update… "+(p.percent??0)+"%");else if(p.stage==="verified")setMessage("Download complete. Signature verified.");else if(p.stage==="installing")setMessage("Installing update… Control Center will restart.")})}}}catch(e){console.error(e)}})();return()=>{active=false;if(typeof unlisten==="function")unlisten()}},[]);const currentVersion=desktop?.currentVersion||null;const latestVersion=latest?.version||null;const updateAvailable=Boolean(currentVersion&&latestVersion&&versionGt(latestVersion,currentVersion));const upToDate=Boolean(currentVersion&&latestVersion&&!updateAvailable);const pct=Math.max(0,Math.min(100,Number(progress?.percent)||0));return <div className="desktopUpdate"><div className="updateIcon"><Zap/></div><div className="updateBody"><span className="eyebrow">DESKTOP APP</span><h3>BalticM Control Center</h3>{currentVersion?<p>Current <b>v{currentVersion}</b>{latestVersion&&<> • Latest <b>v{latestVersion}</b></>}</p>:<p>{latest?.available?<>Latest desktop release <b>v{latest.version}</b>.</>:"Desktop release information unavailable."}</p>}<div className="updateActions"><button className="checkUpdate" onClick={check} disabled={checking||installing}><Activity/>{checking?"Checking…":"Check for updates"}</button>{upToDate&&<span className="updateReady"><span/>UP TO DATE</span>}{updateAvailable&&nativeInvoke&&<button className="checkUpdate" onClick={install} disabled={installing}>{installing?(progress?.stage==="installing"?"Installing…":"Downloading… "+pct+"%"):"Download & Install Update"}</button>}{!currentVersion&&latest?.available&&<span className="updateReady"><span/>LATEST v{latest.version}</span>}</div>{installing&&progress&&<div className="updateProgress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow={pct}><div className="updateProgressBar" style={{width:pct+"%"}}/></div>}{message&&<small>{message}</small>}{currentVersion?<small>Signed native updater. The app stays open while downloading and closes only when installation starts.</small>:<small>Open BalticM Control Center to check and install signed desktop updates.</small>}</div></div>}

function Card({icon:I,label,value,sub}){const text=String(value||"");const ratio=text.match(/^(\d+)\/(\d+)$/);const healthy=!!ratio&&ratio[1]===ratio[2]&&ratio[1]!=="0";const tone=/ONLINE|READY|CONNECTED/.test(text)||healthy?" ok":/OFFLINE|ATTENTION/.test(text)?" bad":"";return <div className={"card"+tone}><div className="ico"><I/></div><div><span>{label}</span><b>{value}</b><small>{sub}</small></div></div>}
function Service({name,desc,state}){let s=state===undefined?null:!!state?.ok;return <div className="service"><div className={"dot "+(s===null?"wait":s?"ok":"bad")}/><div><b>{name}</b><span>{desc}</span></div><strong>{s===null?"CHECKING":s?"ONLINE":"OFFLINE"}</strong></div>}
